SELECT CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN p.category = 'Sports' THEN p.stock_qty ELSE 0 END) AS sports_stock_qty FROM products p LEFT JOIN suppliers s ON p.supplier_id = s.id WHERE p.supplier_id IN (5, 11, 26) GROUP BY CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.6 THEN 'mid' ELSE 'low' END;
